from openpyxl import load_workbook

file_path = "data/order_summary.xlsx"
order_id = "ORD-6C71B1"

workbook = load_workbook(file_path)
updated = False

for worksheet in workbook.worksheets:
    headers = {
        str(cell.value).strip().lower(): cell.column
        for cell in worksheet[1]
        if cell.value is not None
    }

    order_col = next(
        (headers[name] for name in ("order id", "order_id", "orderid") if name in headers),
        None,
    )
    status_col = headers.get("status") or headers.get("order status")

    if order_col and status_col:
        for row in range(2, worksheet.max_row + 1):
            if str(worksheet.cell(row, order_col).value).strip() == order_id:
                current_status = str(
                    worksheet.cell(row, status_col).value
                ).strip().lower()

                if current_status != "cancelled":
                    raise ValueError(
                        f"{order_id} currently has status {current_status!r}, "
                        "not 'cancelled'. No change was saved."
                    )

                worksheet.cell(row, status_col).value = "confirmed"
                updated = True
                break

    if updated:
        break

if not updated:
    raise ValueError(f"Could not find {order_id} with the required columns.")

workbook.save(file_path)
print(f"Updated {order_id} from 'cancelled' to 'confirmed' in {file_path}.")
